在下列代码的横线处填写（），使得输出是 “ 20 10 ” 。
```cpp
#include <iostream>
using namespace std;
int main() {
    int a = 10, b = 20;
    cout << a + b << " " << ________ << endl;
    return 0;
}
```

在下列代码的横线处填写（），可以使得输出是 “ 147 ” 。
```cpp
#include <iostream>
using namespace std;
int main() {
    for (int i = 1; i <= 7; i++) {
        if (________) cout << i;
    }
    return 0;
}
```

执行以下 C++ 语言程序后，输出结果是（）。
```cpp
#include <iostream>
using namespace std;
int main() {
    int n = 5, sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i * i;
    }
    cout << sum << endl;
    return 0;
}
```
